"""`repairlib catalog`: every CLI command and MCP tool with its arguments, generated by reflection.

Nothing here is a hand-kept list. CLI entries come from walking the argparse parser; MCP entries come from
the tool definitions the MCP registry already builds. A new command or tool therefore appears on its own.
"""

import argparse
import json
from collections.abc import Iterable

SCALAR_TYPES = {int: "integer", float: "number", bool: "boolean"}
SKIPPED_DESTS = {"help"}


def _subparsers(parser):
    return next((a for a in parser._actions if isinstance(a, argparse._SubParsersAction)), None)


def _argument_type(action) -> str:
    if isinstance(action, (argparse._StoreTrueAction, argparse._StoreFalseAction)):
        return "boolean"
    return SCALAR_TYPES.get(action.type, "string")


def _argument(action) -> dict:
    flags = [flag for flag in action.option_strings]
    entry = {
        "name": flags[-1] if flags else action.dest,
        "flags": flags,
        "type": _argument_type(action),
        "required": bool(action.required) if flags else action.nargs not in ("?", "*"),
        "help": "" if action.help in (None, argparse.SUPPRESS) else str(action.help),
    }
    if action.choices is not None:
        entry["choices"] = sorted(str(choice) for choice in action.choices)
    # Defaults are shown only when they are plain numbers or booleans; string defaults can hold local paths.
    if isinstance(action.default, (bool, int, float)):
        entry["default"] = action.default
    return entry


def _arguments(parser) -> list[dict]:
    actions = [a for a in parser._actions
               if not isinstance(a, (argparse._HelpAction, argparse._SubParsersAction))
               and a.help != argparse.SUPPRESS and a.dest not in SKIPPED_DESTS]
    return sorted((_argument(a) for a in actions), key=lambda a: (not a["required"], a["name"]))


def cli_operations(parser, prefix=()) -> Iterable[dict]:
    """One entry per runnable command path: every leaf, and every group whose subcommand is optional."""
    group = _subparsers(parser)
    if group is None:
        return
    summaries = {choice.dest: choice.help or "" for choice in group._choices_actions}
    for name, child in group.choices.items():
        path = (*prefix, name)
        nested = _subparsers(child)
        if nested is None or not nested.required:
            yield {"surface": "cli", "name": " ".join(path), "description": summaries.get(name, ""),
                   "arguments": _arguments(child)}
        yield from cli_operations(child, path)


def _schema_type(schema: dict) -> str:
    if "type" in schema:
        return schema["type"] if isinstance(schema["type"], str) else "|".join(sorted(schema["type"]))
    options = schema.get("anyOf") or schema.get("oneOf") or []
    kinds = sorted({option.get("type", "object") for option in options})
    return "|".join(kinds) if kinds else "any"


def mcp_operations(tools) -> Iterable[dict]:
    for tool in tools:
        schema = tool.input_schema or {}
        required = set(schema.get("required", ()))
        arguments = [{"name": name, "type": _schema_type(spec), "required": name in required,
                      "description": spec.get("description", "")}
                     for name, spec in schema.get("properties", {}).items()]
        arguments.sort(key=lambda a: (not a["required"], a["name"]))
        annotations = tool.annotations
        yield {"surface": "mcp", "name": tool.name, "description": tool.description or "",
               "read_only": bool(annotations and annotations.read_only_hint), "arguments": arguments}


def build_catalog(parser, tools) -> dict:
    operations = [*cli_operations(parser), *mcp_operations(tools)]
    operations.sort(key=lambda entry: (entry["surface"], entry["name"]))
    return {"operations": operations}


def _argument_text(argument: dict) -> str:
    mark = "" if argument["required"] else "?"
    return f"{argument['name']}{mark}:{argument['type']}"


def render_text(catalog: dict) -> str:
    lines = []
    for entry in catalog["operations"]:
        arguments = " ".join(_argument_text(a) for a in entry["arguments"]) or "-"
        description = " ".join(entry["description"].split())
        lines.append(f"{entry['surface']}\t{entry['name']}\t{arguments}\t{description}")
    return "\n".join(lines)


def _mcp_tools():
    from repairlib.adapters.mcp import tool_definitions
    return tool_definitions()


def run_catalog_command(args, parser) -> int:
    catalog = build_catalog(parser, _mcp_tools())
    if args.json:
        print(json.dumps(catalog, ensure_ascii=False, sort_keys=True, indent=2))
    else:
        print(render_text(catalog))
    return 0
